package dz.local.mealguard;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import org.robolectric.shadows.ShadowAlertDialog;import android.app.AlertDialog;import android.view.*;import android.widget.*;import org.json.*;import java.lang.reflect.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,35})
public class ReplacementActivityTest {
 void field(MainActivity a,String name,Object value)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(a,value);}
 String text(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(text(((ViewGroup)v).getChildAt(i)));return s.toString();}
 @Test public void replacementRequiresSeparateExplicitConsentAndCancelHasNoEffects()throws Exception{Vault vault=new Vault(RuntimeEnvironment.getApplication());vault.clear();try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();JSONObject cfg=new JSONObject().put("breakfast_id",10).put("lunch_id",20).put("dinner_id",10);JSONArray depots=new JSONArray().put(new JSONObject().put("id",10).put("nameFR","Old dorm").put("breakfast",true).put("lunch",true).put("dinner",true)).put(new JSONObject().put("id",20).put("nameFR","New lunch").put("lunch",true));java.time.LocalDate day=Engine.today();JSONArray rows=new JSONArray().put(new JSONObject().put("id",77).put("date_reserve",day.plusDays(1).toString()).put("mealtype_fr","lunch").put("depot_fr","Old dorm"));Replacement.Review review=Replacement.inspect(cfg,depots,rows,day);field(a,"preview",review.plan);field(a,"conflicts",review.conflicts);field(a,"previewAccount",cfg);field(a,"previewDay",day);Method method=MainActivity.class.getDeclaredMethod("confirmReplacement");method.setAccessible(true);method.invoke(a);AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();String shown=text(d.getWindow().getDecorView());assertTrue(shown.contains("Old dorm"));assertTrue(shown.contains("New lunch"));assertTrue(shown.contains("77"));assertTrue(shown.contains("فتفقد حجز الوجبة"));assertTrue(shown.contains("أوافق — استبدال"));assertNull(Shadows.shadowOf(a).getNextStartedActivity());d.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertFalse(d.isShowing());assertFalse(vault.enabled());assertEquals(0,vault.lastSuccess());}finally{vault.clear();}}
}
